INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33711, 'Matthew 27:6', 'Matthew', 27, 6, 'خو مشرانو کاهنانو هغه پیسې راواخیستې او ویې ویل: «د خدای د کور په خزانه کې د دې پیسو اچول روا نه دي، ځکه چې دا د انسان د ژوند بیه ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_6.mp3', '', 1761754199, 1761754199),
(33712, 'Matthew 27:7', 'Matthew', 27, 7, 'نو هغوی په خپلو کې مشوره وکړه او په هغو پیسو یې د کلال ځمکه واخیستله چې د غیریهودیانو دپاره په کې هدیره جوړه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_7.mp3', '', 1761754199, 1761754199),
(33713, 'Matthew 27:8', 'Matthew', 27, 8, 'نو له دې امله هغه ځمکه تر نن ورځې پورې «د وینو د پټي» په نوم یادیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_8.mp3', '', 1761754199, 1761754199),
(33714, 'Matthew 27:9', 'Matthew', 27, 9, 'په دې ډول د ارمیا نبي هغه پېشګویي رښتیا شوه چې وایي: «هغوی د سپینو زرو دېرش سکې یعنې د هغه د سر بیه چې د اسراییلو د قوم له خوا ټاکل شوې وه، واخیستلې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_9.mp3', '', 1761754199, 1761754199),
(33715, 'Matthew 27:10', 'Matthew', 27, 10, 'او په هغو پیسو باندې یې د کلال ځمکه واخیستله، لکه څنګه چې څښتن ماته ویلي وو.» پیلاتوس د عیسی څخه پوښتنې کوي (مرقوس ۱۵‏:‌۲‌‏-‌۵ او لوقا ۲۳‏:‌۳‌‏-‌۵ او یوحنا ۱۸‏:‌۳۳‌‏-‌۳۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_10.mp3', '', 1761754199, 1761754199),
(33716, 'Matthew 27:11', 'Matthew', 27, 11, 'بیا یې عیسی پیلاتوس والي ته راوست او والي ترې پوښتنه وکړه: «ایا ته د یهودیانو پاچا یې؟» عیسی وویل: «ته په خپله وایې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_11.mp3', '', 1761754199, 1761754199),
(33717, 'Matthew 27:12', 'Matthew', 27, 12, 'خو کله چې د مشرانو کاهنانو او قومي مشرانو له خوا په هغه تور ولګول شو، نو هغه په ځواب کې هېڅ ونه ویل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_12.mp3', '', 1761754199, 1761754199),
(33718, 'Matthew 27:13', 'Matthew', 27, 13, 'بیا پیلاتوس هغه ته وویل: «هغوی چې ستا په خلاف کومه شاهدي ورکوي ته یې نه اورې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_13.mp3', '', 1761754199, 1761754199),
(33719, 'Matthew 27:14', 'Matthew', 27, 14, 'خو عیسی یوه خبره هم ونه کړه او والي ډېر حیران شو. عیسی ته د مرګ سزا ورکول کیږي (مرقوس ۱۵‏:‌۶‌‏-‌۱۵ او لوقا ۲۳‏:‌۱۳‌‏-‌۲۵ او یوحنا ۱۸‏:‌۳۹ ‏- ۱۹‏:‌۱۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_14.mp3', '', 1761754199, 1761754199),
(33720, 'Matthew 27:15', 'Matthew', 27, 15, 'د اختر په ورځو کې دا رواج ؤ چې والي به یو بندي د خلکو په خوښه د زندان ‎څخه ازاداوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_15.mp3', '', 1761754199, 1761754199),
(33721, 'Matthew 27:16', 'Matthew', 27, 16, 'په هغه وخت کې د باراباس په نامه یو بدنام سړی بندي ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_16.mp3', '', 1761754199, 1761754199),
(33722, 'Matthew 27:17', 'Matthew', 27, 17, 'کله چې خلک سره راټول شول، نو پیلاتوس د هغوی نه پوښتنه وکړه: «تاسو څوک غواړئ چې درته یې ازاد کړم، باراباس یا عیسی چې مسیح ورته وایي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_17.mp3', '', 1761754199, 1761754199),
(33723, 'Matthew 27:18', 'Matthew', 27, 18, 'ځکه چې هغه په دې پوهېده چې هغوی د بخیلۍ له مخې عیسی هغه ته په لاس ورکړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_18.mp3', '', 1761754199, 1761754199),
(33724, 'Matthew 27:19', 'Matthew', 27, 19, 'کله چې هغه د قضاوت په چوکۍ ناست ؤ، نو ښځې یې ورته دا پیغام راولېږه: «د هغه بې‌ګناه سړي سره کار مه لره، ځکه پرون شپه چې ما د هغه په هکله کوم خوب ولیده، نو د هغه له امله ټوله ورځ پرېشانه وم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_19.mp3', '', 1761754199, 1761754199),
(33725, 'Matthew 27:20', 'Matthew', 27, 20, 'خو مشرانو کاهنانو او قومي مشرانو خلک دې ته هڅول چې د پیلاتوس څخه وغواړي چې باراباس ورته ازاد کړي او عیسی اعدام کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_20.mp3', '', 1761754199, 1761754199),
(33726, 'Matthew 27:21', 'Matthew', 27, 21, 'والي یوځل بیا هغوی ته وویل: «په دې دواړو کې تاسو څوک غواړئ چې درته یې ازاد کړم؟» هغوی وویل: «باراباس.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_21.mp3', '', 1761754199, 1761754199),
(33727, 'Matthew 27:22', 'Matthew', 27, 22, 'پیلاتوس د هغوی څخه پوښتنه وکړه: «نو بیا د عیسی سره چې د مسیح په نوم یادیږي څه وکړم؟» هغوی ټولو وویل: «هغه په صلیب باندې ځوړند کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_22.mp3', '', 1761754199, 1761754199),
(33728, 'Matthew 27:23', 'Matthew', 27, 23, 'خو پیلاتوس وویل: «ولې؟ هغه څه جرم کړی دی؟» هغوی چیغې نورې هم زیاتې کړې: «هغه په صلیب باندې ځوړند کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_23.mp3', '', 1761754199, 1761754199),
(33729, 'Matthew 27:24', 'Matthew', 27, 24, 'خو کله چې پیلاتوس پوه شو چې هغه هېڅ نه شي کولای او کېدای شي چې شور او غوغا جوړه شي، نو اوبه یې راواخیستې او د خلکو په مخکې یې خپل لاسونه ووینځل او ویې ویل: «زه د دې سړي د مرګ مسوول نه یم، دا ستاسو کار دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_24.mp3', '', 1761754199, 1761754199),
(33730, 'Matthew 27:25', 'Matthew', 27, 25, 'ټولو خلکو ځواب ورکړ: «د دې سړي خون دې زمونږ او زمونږ د اولادونو په غاړه وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_25.mp3', '', 1761754199, 1761754199),
(33731, 'Matthew 27:26', 'Matthew', 27, 26, 'نو پیلاتوس باراباس د هغوی دپاره ازاد کړ او بیا یې حکم وکړ چې عیسی دې په دورو باندې ووهل شي او په صلیب باندې دې ځوړند کړای شي. عسکر په عیسی باندې ملنډې وهي (مرقوس ۱۵‏:‌۱۶‌‏-‌۲۰ او یوحنا ۱۹‏:‌۲، ۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_26.mp3', '', 1761754199, 1761754199),
(33732, 'Matthew 27:27', 'Matthew', 27, 27, 'بیا د پیلاتوس عسکرو عیسی د والي د ماڼۍ حوېلۍ ته بوتو او ټول کنډک یې ترې راچاپېر کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_27.mp3', '', 1761754199, 1761754199),
(33733, 'Matthew 27:28', 'Matthew', 27, 28, 'کالي یې ترې وویستل او سور رنګې چپنه یې ورته ورواغوستله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_28.mp3', '', 1761754199, 1761754199),
(33734, 'Matthew 27:29', 'Matthew', 27, 29, 'بیا یې د اغزیو څخه یو تاج جوړ کړ او په سر یې ورته کېښود او په ښي لاس کې یې ورته یو لرګی ورکړ. بیا د هغه په مخکې په ګونډو شول، ملنډې یې ورباندې وهلې او ویل یې: «ژوندی دې وي د یهودیانو پاچا.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_29.mp3', '', 1761754199, 1761754199),
(33735, 'Matthew 27:30', 'Matthew', 27, 30, 'په هغه یې لاړې ورتو کړې او لرګی یې ترې واخیست او په سر یې پرې وواهه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_30.mp3', '', 1761754199, 1761754199),
(33736, 'Matthew 27:31', 'Matthew', 27, 31, 'کله چې هغوی ملنډې وهل بس کړل، نو چپنه یې ترې وویستله او خپل کالي یې ورته بېرته ورواغوستل. بیا یې هغه بوتو چې په صلیب یې ځوړند کړي. عیسی په صلیب باندې مېخ کیږي (مرقوس ۱۵‏:‌۲۱‌‏-‌۳۲ او لوقا ۲۳‏:‌۲۶‌‏-‌۴۳ او یوحنا ۱۹‏:‌۱۷‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_31.mp3', '', 1761754199, 1761754199),
(33737, 'Matthew 27:32', 'Matthew', 27, 32, 'هغوی روان وو چې په لاره کې د شمعون په نوم یو سړي سره چې د قیروان څخه ؤ مخامخ شول او عسکرو هغه مجبوره کړ چې د عیسی صلیب یوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_32.mp3', '', 1761754199, 1761754199),
(33738, 'Matthew 27:33', 'Matthew', 27, 33, 'کله چې هغوی د جلجتا په نوم یوځای ته چې معنی یې د سر د کوپړۍ ځای دی، ورسېدل،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_33.mp3', '', 1761754199, 1761754199),
(33739, 'Matthew 27:34', 'Matthew', 27, 34, 'هلته یې عیسی ته داسې شراب چې ترخه شیان په کې ګډ شوي وو ورکړل. خو کله چې یې وڅکل، نو ویې نه غوښتل چې ویې څښي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_34.mp3', '', 1761754199, 1761754199),
(33740, 'Matthew 27:35', 'Matthew', 27, 35, 'کله چې هغه یې په صلیب باندې مېخ کړ، نو د هغه په کالیو یې پچه واچوله او په خپل منځ کې یې سره ووېشل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_35.mp3', '', 1761754199, 1761754199),
(33741, 'Matthew 27:36', 'Matthew', 27, 36, 'بیا هغوی کښېناستل او د هغه پهره یې کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_36.mp3', '', 1761754199, 1761754199),
(33742, 'Matthew 27:37', 'Matthew', 27, 37, 'د هغه د سر دپاسه یې یوه تخته ځوړنده کړه چې د هغه جرم په کې لیکل شوی ؤ: «دا د یهودیانو پاچا عیسی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_37.mp3', '', 1761754199, 1761754199),
(33743, 'Matthew 27:38', 'Matthew', 27, 38, 'د هغه سره دوه داړه ماران هم په صلیب ځړول شوي وو، چې یو یې ښي لاس ته او بل یې چپ لاس ته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_38.mp3', '', 1761754199, 1761754199),
(33744, 'Matthew 27:39', 'Matthew', 27, 39, 'څوک چې له هغه ځای څخه تېرېدل، نو خپل سرونه به یې خوځول او عیسی ته به یې ښکنځلې کولې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_39.mp3', '', 1761754199, 1761754199),
(33745, 'Matthew 27:40', 'Matthew', 27, 40, 'او ویل به یې: «تا غوښتل چې د خدای کور وران کړې او په درې ورځو کې یې بېرته جوړ کړې. که ته په رښتیا د خدای زوی یې، نو خپل ځان وژغوره او د صلیب څخه راښکته شه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_40.mp3', '', 1761754199, 1761754199),
(33746, 'Matthew 27:41', 'Matthew', 27, 41, 'همدارنګه مشرانو کاهنانو، د شریعت عالمانو او یهودي مشرانو په هغه باندې ملنډې وهلې او ویل یې:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_41.mp3', '', 1761754199, 1761754199),
(33747, 'Matthew 27:42', 'Matthew', 27, 42, '«هغه نور خلک ژغورل، خو خپل ځان نه شي ژغورلی. که چېرې هغه د اسراییلو پاچا وي، نو د صلیب څخه دې راښکته شي، نو بیا به مونږ ورباندې ایمان راوړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_42.mp3', '', 1761754199, 1761754199),
(33748, 'Matthew 27:43', 'Matthew', 27, 43, 'هغه په خدای توکل درلود او دعوه یې کوله چې د خدای زوی یم، نو که خدای غواړي اوس دې هغه وژغوري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_43.mp3', '', 1761754199, 1761754199),
(33749, 'Matthew 27:44', 'Matthew', 27, 44, 'همدارنګه هغه داړه مارانو چې د هغه سره په صلیب ځړول شوي وو هم هغه ته ښکنځلې کولې. د عیسی مړینه (مرقوس ۱۵‏:‌۳۳‌‏-‌۴۱ او لوقا ۲۳‏:‌۴۴‌‏-‌۴۹ او یوحنا ۱۹‏:‌۲۸‌‏-‌۳۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_44.mp3', '', 1761754199, 1761754199),
(33750, 'Matthew 27:45', 'Matthew', 27, 45, 'د غرمې د دولسو بجو نه د ماسپښین تر درې بجو پورې په ټول وطن کې تیاره راخپره شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_45.mp3', '', 1761754199, 1761754199),
(33751, 'Matthew 27:46', 'Matthew', 27, 46, 'شاوخوا درې بجې وې چې عیسی په زوره زوره چیغه ووهله: «ایلي، ایلي، لما سبقتني؟ یعنې ای زما خدایه، ای زما خدایه، زه دې ولې پرېښودم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_46.mp3', '', 1761754199, 1761754199),
(33752, 'Matthew 27:47', 'Matthew', 27, 47, 'ځینو خلکو چې په هغه ځای کې ولاړ وو، دا واورېدل او ویې ویل: «هغه الیاس نبي ته نارې وهي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_47.mp3', '', 1761754199, 1761754199),
(33753, 'Matthew 27:48', 'Matthew', 27, 48, 'د هغوی څخه یو تن سمدلاسه منډه کړه، اسفنج یې راواخیست او په تروو شرابو کې یې لوند کړ او د لرګي په څوکه یې کېښود او عیسی ته یې ورکړ چې ویې څښي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_48.mp3', '', 1761754199, 1761754199),
(33754, 'Matthew 27:49', 'Matthew', 27, 49, 'خو نورو وویل: «صبر وکړئ، پرېږده وګورو چې الیاس نبي د هغه د خلاصولو دپاره راځي او که نه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_49.mp3', '', 1761754199, 1761754199),
(33755, 'Matthew 27:50', 'Matthew', 27, 50, 'عیسی یوځل بیا په لوړ اواز چیغه ووهله او ساه یې ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_50.mp3', '', 1761754199, 1761754199),
(33756, 'Matthew 27:51', 'Matthew', 27, 51, 'هغه وخت د خدای د کور پرده د سر نه تر بېخه پورې په منځ کې دوه ټوټې شوه. زلزله شوه او د تیږو تختې وچاودلې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_51.mp3', '', 1761754199, 1761754199),
(33757, 'Matthew 27:52', 'Matthew', 27, 52, 'قبرونه پرانیستل شول او هغه ډېر سپېڅلي خلک چې د مرګ په خوب ویده وو بیا راژوندي شول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_52.mp3', '', 1761754199, 1761754199),
(33758, 'Matthew 27:53', 'Matthew', 27, 53, 'او د خپلو قبرونو څخه راووتل او د عیسی د راژوندي کېدلو څخه وروسته د اورشلیم سپېڅلي ښار ته لاړل او ډېرو خلکو ته ښکاره شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_53.mp3', '', 1761754199, 1761754199),
(33759, 'Matthew 27:54', 'Matthew', 27, 54, 'کله چې هغه رومي منصبدار او د هغه عسکرو چې د عیسی پهره یې کوله، زلزله او ټولې پېښې ولیدلې، نو ډېر ووېرېدل او ویې ویل: «هغه په رښتیا د خدای زوی ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_54.mp3', '', 1761754199, 1761754199),
(33760, 'Matthew 27:55', 'Matthew', 27, 55, 'په هغه ځای کې ډېرو ښځو چې د جلیل څخه د عیسی د خدمت دپاره راغلې وې د لېرې نه دا هرڅه لیدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_55.mp3', '', 1761754199, 1761754199),
(33761, 'Matthew 27:56', 'Matthew', 27, 56, 'په هغوی کې مریم مجدلیه، د یعقوب او یوسف مور مریم او د زبدي د زامنو مور وه. د عیسی ښخول (مرقوس ۱۵‏:‌۴۲‌‏-‌۴۷ او لوقا ۲۳‏:‌۵۰‌‏-‌۵۶ او یوحنا ۱۹‏:‌۳۸‌‏-‌۴۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_56.mp3', '', 1761754199, 1761754199),
(33762, 'Matthew 27:57', 'Matthew', 27, 57, 'کله چې ماښام شو، نو یو شتمن سړی چې یوسف نومېده او د رامه د ښار څخه ؤ چې هغه هم د عیسی شاګرد شوی ؤ راغی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_57.mp3', '', 1761754199, 1761754199),
(33763, 'Matthew 27:58', 'Matthew', 27, 58, 'هغه پیلاتوس ته ورغی او د هغه څخه یې د عیسی مړی وغوښت. نو پیلاتوس امر وکړ چې هغه ورته ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_58.mp3', '', 1761754199, 1761754199),
(33764, 'Matthew 27:59', 'Matthew', 27, 59, 'یوسف هغه مړی یووړ او په یو سپین کفن کې یې تاو کړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_59.mp3', '', 1761754199, 1761754199),
(33765, 'Matthew 27:60', 'Matthew', 27, 60, 'او په هغه قبر کې یې کېښود چې یوسف د خپل ځان دپاره په یو ګټ کې کیندلی ؤ. بیا یې یوه غټه تیږه د قبر خولې ته راورغړوله او لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_60.mp3', '', 1761754199, 1761754199),
(33766, 'Matthew 27:61', 'Matthew', 27, 61, 'مریم مجدلیه او هغه بله مریم دواړه قبر ته مخامخ ناستې وې. د عیسی د قبر ساتونکي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_61.mp3', '', 1761754199, 1761754199),
(33767, 'Matthew 27:62', 'Matthew', 27, 62, 'په بله ورځ چې د سبت ورځ وه، مشران کاهنان او فریسیان پیلاتوس ته ورغلل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_62.mp3', '', 1761754199, 1761754199),
(33768, 'Matthew 27:63', 'Matthew', 27, 63, 'او ویې ویل: «ښاغلیه! مونږ ته په یاد دي هغه چلباز چې لا ژوندی ؤ ویلي یې وو چې درې ورځې وروسته به زه بیا راژوندی شم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_63.mp3', '', 1761754199, 1761754199),
(33769, 'Matthew 27:64', 'Matthew', 27, 64, 'نو امر وکړئ چې تر درېو ورځو پورې دې د دې قبر ښه ساتنه وشي، هسې نه چې شاګردان یې راشي او د هغه مړی په غلا یوسي او خلکو ته ووایي چې هغه د مرګ څخه وروسته بیا راژوندی شوی دی او وروستنۍ غولونه به یې د لومړنۍ غولونې څخه ډېره بده وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_64.mp3', '', 1761754199, 1761754199),
(33770, 'Matthew 27:65', 'Matthew', 27, 65, 'پیلاتوس هغوی ته وویل: «ساتونکي درسره واخلئ، لاړ شئ او څنګه چې کولای شئ د هغه قبر ساتنه وکړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_65.mp3', '', 1761754199, 1761754199),
(33771, 'Matthew 27:66', 'Matthew', 27, 66, 'نو هغوی لاړل او د قبر په تیږه باندې یې نښه ولګوله چې څوک یې ونه خوځوي او ساتونکي یې ورباندې ودرول چې ساتنه یې وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_66.mp3', '', 1761754199, 1761754199),
(33772, 'Matthew 10:1', 'Matthew', 10, 1, 'عیسی خپل دولس شاګردان راوغوښتل او هغوی ته یې د پېریانو د ویستلو او د هر ډول ناروغیو او کمزورتیاوو د روغولو اختیار ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_1.mp3', '', 1761754199, 1761754199),
(33773, 'Matthew 10:2', 'Matthew', 10, 2, 'د هغو دولسو رسولانو نومونه دا دي: لومړنی شمعون چې په پطروس مشهور ؤ او ورور یې اندریاس، یعقوب د زبدي زوی او د هغه ورور یوحنا،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_2.mp3', '', 1761754199, 1761754199),
(33774, 'Matthew 10:3', 'Matthew', 10, 3, 'فیلیپوس او بارتولما، توما او مالیه ټولوونکی متي، یعقوب د حلفي زوی او تدي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_3.mp3', '', 1761754199, 1761754199),
(33775, 'Matthew 10:4', 'Matthew', 10, 4, 'شمعون سرتېری او یهودا اسخریوتي چې د عیسی سره یې خیانت وکړ. عیسی خپل دولس رسولان لېږي چې خپل کار سرته ورسوي (مرقوس ۶‏:‌۷‌‏-‌۱۳ او لوقا ۹‏:‌۱‌‏-‌۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_4.mp3', '', 1761754199, 1761754199),
(33776, 'Matthew 10:5', 'Matthew', 10, 5, 'عیسی دا دولس شاګردان د دې لارښوونو سره ولېږل: «د غیریهودیانو هېڅ یوې سیمې ته لاړ نه شئ او د سامریانو هېڅ ښار ته مه ننوځئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_5.mp3', '', 1761754199, 1761754199),
(33777, 'Matthew 10:6', 'Matthew', 10, 6, 'خو د هغې په ځای د اسراییلو قوم ته چې د ورک شویو پسونو په شان دي ورشئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_6.mp3', '', 1761754199, 1761754199),
(33778, 'Matthew 10:7', 'Matthew', 10, 7, 'او په لاره کې دا پیغام ورکوئ چې اسماني پاچاهي رانژدې شوې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_7.mp3', '', 1761754199, 1761754199),
(33779, 'Matthew 10:8', 'Matthew', 10, 8, 'ناروغان روغ کړئ، مړي راژوندي کړئ، په جذام اخته خلک پاک او روغ کړئ او پېریان وباسئ. تاسو ته وړیا درکړل شوي او وړیا یې ورکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_8.mp3', '', 1761754199, 1761754199),
(33780, 'Matthew 10:9', 'Matthew', 10, 9, 'د ځان سره د سرو زرو، سپینو زرو او مسو سکې مه وړئ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_9.mp3', '', 1761754199, 1761754199),
(33781, 'Matthew 10:10', 'Matthew', 10, 10, 'د سفر دپاره کوم خورجین، اضافه کالي، څپلۍ او امسا مه اخلئ، ځکه چې مزدور د خپلې مزدورۍ حقدار دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_10.mp3', '', 1761754199, 1761754199),
(33782, 'Matthew 10:11', 'Matthew', 10, 11, 'کله چې کوم ښار یا کوم کلي ته ننوځئ، نو د یو داسې سړي کور ته ورشئ چې د ورتلو لایق وي او ترڅو پورې چې کوم بل ځای ته ځئ، نو تر هغه وخته پورې د هغه په کور کې پاتې شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_11.mp3', '', 1761754199, 1761754199),
(33783, 'Matthew 10:12', 'Matthew', 10, 12, 'کوم کور ته چې ننوځئ، نو په هغه سلام واچوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_12.mp3', '', 1761754199, 1761754199),
(33784, 'Matthew 10:13', 'Matthew', 10, 13, 'که چېرې د هغه کور خلک ستاسو د سلام لایق وي، نو کومه سوله او سلامتي چې تاسو یې د هغوی دپاره غواړئ هغه به ورباندې پاتې شي، خو که لایق یې نه وي، نو هغه سلام به بېرته تاسو ته راوګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_13.mp3', '', 1761754199, 1761754199),
(33785, 'Matthew 10:14', 'Matthew', 10, 14, 'خو که چېرې څوک تاسو ته هرکلی ونه وایي او یا ستاسو خبرو ته غوږ ونه نیسي، نو کله چې د هغه کور یا ښار څخه ځئ، نو د خپلو پښو خاورې وڅنډئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_14.mp3', '', 1761754199, 1761754199),
(33786, 'Matthew 10:15', 'Matthew', 10, 15, 'په یقین سره زه تاسو ته دا وایم چې د قیامت په ورځ به د سدوم او عموره د ښارونو د خلکو سزا د دی ښار د خلکو د سزا څخه کمه وي. د راتلونکې ځورونې په هکله (مرقوس ۱۳‏:‌۹‌‏-‌۱۳ او لوقا ۲۱‏:‌۱۲‌‏-‌۱۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_15.mp3', '', 1761754199, 1761754199),
(33787, 'Matthew 10:16', 'Matthew', 10, 16, 'ګورئ، زه تاسو لکه د پسونو په شان د لېوانو منځ ته لېږم، نو د مارانو په شان هوښیار او د کوترو په شان بې‌آزاره اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_16.mp3', '', 1761754199, 1761754199),
(33788, 'Matthew 10:17', 'Matthew', 10, 17, 'پام کوئ چې خلک به تاسو محکمو ته وسپاري او په خپلو کنیسو کې به مو په دورو باندې ووهي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_17.mp3', '', 1761754199, 1761754199),
(33789, 'Matthew 10:18', 'Matthew', 10, 18, 'او زما په خاطر به تاسو والیانو او پاچاهانو ته راوستل شئ چې د هغوی او غیریهودیانو په مخکې شاهدي ورکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_18.mp3', '', 1761754199, 1761754199),
(33790, 'Matthew 10:19', 'Matthew', 10, 19, 'خو کله چې هغوی تاسو محکمې ته راولي، نو په دې هکله اندېښنه مه کوئ چې تاسو به څه وایئ او څنګه به یې وایئ، ځکه چې په هماغه ساعت به تاسو ته وویل شي چې څه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_19.mp3', '', 1761754199, 1761754199),
(33791, 'Matthew 10:20', 'Matthew', 10, 20, 'ځکه تاسو چې کومې خبرې کوئ هغه به ستاسو خبرې نه وي، بلکې ستاسو د اسماني پلار روح به ستاسو په وسیله خبرې کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_20.mp3', '', 1761754199, 1761754199),
(33792, 'Matthew 10:21', 'Matthew', 10, 21, 'ورور به د ورور سره خیانت وکړي چې ووژل شي او پلار به د خپلو اولادونو سره. اولادونه به د خپلو میندو او پلرونو په خلاف راپورته شي او د هغوی د مړینې سبب به شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_21.mp3', '', 1761754199, 1761754199),
(33793, 'Matthew 10:22', 'Matthew', 10, 22, 'ټول خلک به زما د نوم په خاطر ستاسو څخه کرکه کوي. خو څوک چې تر اخره ټینګ پاتې شي، هغه به خلاصون ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_22.mp3', '', 1761754199, 1761754199),
(33794, 'Matthew 10:23', 'Matthew', 10, 23, 'کله چې څوک تاسو په یو ښار کې ځوروي، نو بل ښار ته وتښتئ. په یقین سره زه تاسو ته دا وایم چې مخکې له دې چې د اسراییلو په ټولو ښارونو کې وګرځئ، د انسان زوی به راشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_23.mp3', '', 1761754199, 1761754199),
(33795, 'Matthew 10:24', 'Matthew', 10, 24, 'شاګرد د خپل استاذ څخه لوی نه دی او نه نوکر د خپل بادار څخه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_24.mp3', '', 1761754199, 1761754199),
(33796, 'Matthew 10:25', 'Matthew', 10, 25, 'د یو شاګرد دپاره دا بس دی چې د خپل استاذ په شان شي او نوکر د خپل بادار په شان. که چېرې د کور مشر ته بعلزبول یعنې شیطان وویل شي، نو د هغه د کورنۍ نور غړي به د دې نه هم په خراب نوم یاد کړای شي. د چا څخه باید ووېرېږئ (لوقا ۱۲‏:‌۲‌‏-‌۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_25.mp3', '', 1761754199, 1761754199),
(33797, 'Matthew 10:26', 'Matthew', 10, 26, 'نو د هغوی نه مه وېرېږئ، ځکه داسې پټ شی نشته چې ښکاره به نه شي او نه داسې پټ راز شته چې ښکاره به نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_26.mp3', '', 1761754199, 1761754199),
(33798, 'Matthew 10:27', 'Matthew', 10, 27, 'څه چې زه تاسو ته په تیاره کې وایم، نو تاسو یې په رڼا ورځ اعلان کړئ، کوم څه چې تاسو ته په غوږ کې وویل شي تاسو یې د بام په سر اعلان کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_27.mp3', '', 1761754199, 1761754199),
(33799, 'Matthew 10:28', 'Matthew', 10, 28, 'د هغو خلکو څخه مه وېرېږئ چې بدن وژني، خو روح نه شي وژلی. خو د هغه چا څخه ووېرېږئ چې بدن او روح دواړه په دوزخ کې تباه کولای شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_28.mp3', '', 1761754199, 1761754199),
(33800, 'Matthew 10:29', 'Matthew', 10, 29, 'ایا دوه مرغۍ په یوه روپۍ نه خرڅیږي؟ خو بیاهم ستاسو د اسماني پلار د رضا څخه پرته یوه هم په ځمکه نه رالویږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_29.mp3', '', 1761754199, 1761754199),
(33801, 'Matthew 10:30', 'Matthew', 10, 30, 'خو ستاسو په هکله باید وویل شي چې ستاسو د سر ویښتان هم شمېرل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_30.mp3', '', 1761754199, 1761754199),
(33802, 'Matthew 10:31', 'Matthew', 10, 31, 'نو بیا مه وېرېږئ، تاسو د بې‌شمېره مرغیو څخه زیات ارزښت لرئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_31.mp3', '', 1761754199, 1761754199),
(33803, 'Matthew 10:32', 'Matthew', 10, 32, 'نو هرڅوک چې د خلکو په مخکې په دې اقرار وکړي چې هغه زما د پیروانو څخه دی، نو زه به هم د خپل اسماني پلار په مخکې اقرار وکړم چې هغه زما د پیروانو څخه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_32.mp3', '', 1761754199, 1761754199),
(33804, 'Matthew 10:33', 'Matthew', 10, 33, 'خو هرڅوک چې د خلکو په مخکې زما څخه انکار وکړي، نو زه به هم د خپل اسماني پلار په مخکې د هغه څخه انکار وکړم. د ایمان په خاطر د ستونزو منل (لوقا ۱۲‏:‌۵۱‌‏-‌۵۳، ۱۴‏:‌۲۶‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_33.mp3', '', 1761754199, 1761754199),
(33805, 'Matthew 10:34', 'Matthew', 10, 34, 'داسې ګومان مه کوئ چې زه د دې دپاره راغلی یم چې نړۍ ته سوله راولم، زه د سولې د راوستلو دپاره نه یم راغلی، بلکې دښمني راولم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_34.mp3', '', 1761754199, 1761754199),
(33806, 'Matthew 10:35', 'Matthew', 10, 35, 'زه راغلی یم چې زوی د پلار، لور د مور او انږور د خواښې په خلاف کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_35.mp3', '', 1761754199, 1761754199),
(33807, 'Matthew 10:36', 'Matthew', 10, 36, 'ستاسو د خپلې کورنۍ غړي به ستاسو دښمنان شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_36.mp3', '', 1761754199, 1761754199),
(33808, 'Matthew 10:37', 'Matthew', 10, 37, 'په چا چې خپل مور او پلار زما څخه زیات ګران وي، نو هغه زما لایق نه دی او په چا چې خپله لور او زوی زما څخه دېر ګران وي، هغه زما لایق نه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_37.mp3', '', 1761754199, 1761754199),
(33809, 'Matthew 10:38', 'Matthew', 10, 38, 'څوک چې خپل صلیب راوانخلي او ما پسې رانه شي، نو هغه زما لایق نه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_38.mp3', '', 1761754199, 1761754199),
(33810, 'Matthew 10:39', 'Matthew', 10, 39, 'څوک چې کوښښ کوي خپل ځان وساتي، نو هغه به له لاسه ورکړي او څوک چې زما په خاطر خپل ژوند له لاسه ورکړي هغه به رښتینی ژوند تر‌لاسه کړي. اجرونه (مرقوس ۹‏:‌۴۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_39.mp3', '', 1761754199, 1761754199);